"""Exact, case-sensitive words; frequency ties prefer first appearance."""


def most_frequent_word(words):
    if not words:
        return None
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    best = words[0]
    for word in words:
        if counts[word] > counts[best]:
            best = word
    return [best, counts[best]]

"""Case-sensitive ASCII A..Z/a..z only; empty strings are valid words."""


def are_anagrams(left, right):
    if any(not ('A' <= ch <= 'Z' or 'a' <= ch <= 'z') for word in (left, right) for ch in word):
        raise ValueError('ASCII letters only')
    if len(left) != len(right):
        return False
    balance = [0] * 128
    for a, b in zip(left, right):
        balance[ord(a)] += 1
        balance[ord(b)] -= 1
    return all(count == 0 for count in balance)

"""Move integer zeroes to the end in place, preserving nonzero order."""


def move_zeroes(values):
    write = 0
    for read in range(len(values)):
        if values[read] != 0:
            values[write] = values[read]
            write += 1
    for index in range(write, len(values)):
        values[index] = 0
    return values

/* C99, single owner; caller supplies capacity valid int slots and distinct
 * control objects. Requests are snapshots passed by value. No allocation,
 * waiting or implicit ISR synchronization. Operations are WRITE then READ.
 */
#include <stdbool.h>
#include <stddef.h>

typedef struct {
    bool valid;
    bool wrote;
    bool read;
    int value; /* meaningful only when read is true */
} FifoResult;

FifoResult fifo_step(int *data, size_t capacity, size_t *read_head,
                     size_t *write_head, bool *is_full, bool *is_empty,
                     bool write_request, int write_value, bool read_request) {
    FifoResult result = {false, false, false, 0};
    if (!data || !read_head || !write_head || !is_full || !is_empty || capacity == 0)
        return result;
    if (*read_head >= capacity || *write_head >= capacity) return result;
    if (*read_head == *write_head ? (*is_full == *is_empty) : (*is_full || *is_empty))
        return result;
    result.valid = true;
    if (write_request && !*is_full) {
        data[*write_head] = write_value;
        *write_head = *write_head + 1 == capacity ? 0 : *write_head + 1;
        *is_empty = false;
        *is_full = *write_head == *read_head;
        result.wrote = true;
    }
    if (read_request && !*is_empty) {
        result.value = data[*read_head];
        *read_head = *read_head + 1 == capacity ? 0 : *read_head + 1;
        *is_full = false;
        *is_empty = *read_head == *write_head;
        result.read = true;
    }
    return result;
}

